def _trakt_lifetime(settings):
    """Use the lifetime returned by Trakt and saved with this sign-in."""
    try:
        lifetime = int(float(settings.getSetting("trakt.lifetime")))
    except (TypeError, ValueError):
        return 604800
    return lifetime if lifetime > 0 else 604800

def _route_nonlibrary_context():
    """Use TMDb Helper's supported sync menu for its non-library items."""
    from urllib.parse import parse_qs, urlsplit
    import xbmcgui

    if kodiUtilities.getMediaType() not in ('movie', 'show', 'season', 'episode'):
        return False
    library_id = xbmc.getInfoLabel('ListItem.DBID').strip()
    if library_id.isdigit() and int(library_id) > 0:
        return False
    for label in ('ListItem.FileNameAndPath', 'ListItem.FolderPath', 'ListItem.Path'):
        path = urlsplit(xbmc.getInfoLabel(label))
        if path.scheme != 'plugin' or path.netloc != 'plugin.video.themoviedb.helper':
            continue
        query = parse_qs(path.query)
        params = {key: value[0] for key, value in query.items() if len(value) == 1}
        tmdb_type = params.get('tmdb_type')
        tmdb_id = params.get('tmdb_id', '')
        if tmdb_type not in ('tv', 'movie') or not tmdb_id.isdigit() or int(tmdb_id) <= 0:
            continue
        parts = ['tmdb_type=' + tmdb_type, 'tmdb_id=' + tmdb_id]
        media_type = kodiUtilities.getMediaType()
        if media_type in ('season', 'episode'):
            season = params.get('season') or xbmc.getInfoLabel('ListItem.Season')
            if not season.isdigit():
                continue
            parts.append('season=' + season)
        if media_type == 'episode':
            episode = params.get('episode') or xbmc.getInfoLabel('ListItem.Episode')
            if not episode.isdigit():
                continue
            parts.append('episode=' + episode)
        xbmc.executebuiltin('RunScript(plugin.video.themoviedb.helper,sync_options,' + ','.join(parts) + ')')
        return True
    xbmcgui.Dialog().ok('Trakt', 'This item has no Kodi library ID. Use its add-on Trakt or Sync options menu.')
    return True

